  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Muscles and How They Work$j$, $j${"readings": [{"title": "Psalm 18 (King James Version)", "url": "/portal/bible/Psalms/18"}], "body": "The body has three kinds of muscle. Skeletal muscles attach to bones and move the body, and you control them on purpose. Smooth muscle lines organs such as the stomach and blood vessels and works without your thinking about it. Cardiac muscle forms the heart and beats all day without rest.\n\nSkeletal muscles pull on bones through strong cords called tendons, and bones meet at joints held by ligaments. Muscles can only pull, not push, so they work in pairs. When the biceps on the front of the upper arm contracts, the triceps on the back relaxes and the elbow bends. Then the triceps contracts and the arm straightens. The quadriceps on the front of the thigh and the hamstrings on the back work as another pair. Major muscle groups include the chest, back, shoulders, arms, abdominals, hips and legs.\n\nMuscles grow stronger when they are worked a bit harder than usual and then given time to recover. Small tears in the muscle fibers repair during rest, and the muscle comes back stronger. This is why rest and sleep matter. Protein, water and good food supply the material for repair. Psalm 18:32 says, It is God that girdeth me with strength, and maketh my way perfect.\n\nMuscles that are not used grow weak. Strong muscles protect joints, improve posture, support the spine, help you move well in sports and daily life, and keep bones strong.\n\nYour task: (1) Name the three kinds of muscle and give a job for each. (2) Explain why muscles work in pairs and name two pairs. (3) Describe how a muscle becomes stronger.\n\nFlorida standards: PE.912.C.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.C.2", "script": "Welcome back. Listen, you are carrying more than 600 muscles, and each one has a job. Today we learn how they work.\n\nThere are three kinds. Skeletal muscles attach to bones and move you, and you control them on purpose. Smooth muscle lines organs like the stomach and blood vessels and works on its own. Cardiac muscle forms the heart and beats all day without rest.\n\nNow watch this. Skeletal muscles pull on bones through tendons. Bones meet at joints that are held by ligaments. A muscle can only pull, never push, so muscles work in pairs. When the biceps contracts, the triceps relaxes and the elbow bends. Then they switch and the arm straightens. The quadriceps and hamstrings in your thigh are another pair.\n\nLook at how muscles grow. When you work a muscle a little harder than usual, tiny tears form in the fibers. During rest, they repair and the muscle comes back stronger. That is why rest, sleep, protein and water matter.\n\nPsalm 18:32 says, It is God that girdeth me with strength, and maketh my way perfect.\n\nYour task is to name the three muscle types, explain muscle pairs, and describe how a muscle grows stronger. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Muscles and How They Work$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Bodyweight and Resistance Training$j$, $j${"readings": [{"title": "Nehemiah 4 (King James Version)", "url": "/portal/bible/Nehemiah/4"}], "body": "Resistance training makes muscles work against a force. The force can be your own body weight, as in push ups and squats, or an object such as a resistance band or a light dumbbell. Bodyweight exercises are an excellent place for a beginner to start because they need no equipment and are easy to control. Nehemiah 4:17 describes builders who worked with one hand and held a weapon in the other, a picture of strength joined with watchfulness.\n\nLearn a few basic moves. The squat works the thighs and hips. Keep the chest up, push the hips back and keep the knees in line with the toes. The push up works the chest, shoulders and arms, and can be done with the knees down or hands on a bench. The plank holds the body straight from head to heels to build the core. The lunge works the legs and balance. The curl up works the abdominal muscles.\n\nUse good form. A set is a group of repetitions, called reps. A beginner might do 1 or 2 sets of 8 to 12 reps with a rest of 30 to 60 seconds between sets, working each major muscle group 2 or 3 days a week with a day of rest in between. Breathe out during the effort, and never hold your breath. Move slowly and with control. Quality matters more than quantity.\n\nSafety rules are firm. Do not attempt to lift the heaviest weight you can, and do not use heavy free weights without a trained adult and a spotter. Use equipment properly. Stop if you feel sharp pain. Be wary of any pill, powder or drug that promises fast muscle, including anabolic steroids, which are dangerous and illegal without a prescription.\n\nYour task: (1) Define resistance training and name five bodyweight exercises. (2) Explain sets and reps and design a beginner routine. (3) List four safety rules for strength training.\n\nFlorida standards: PE.912.M.1, PE.912.L.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.M.1, PE.912.L.3", "script": "Welcome back. Listen, strength is not only for athletes. It protects your joints, helps your posture and makes daily life easier.\n\nResistance training makes muscles work against a force. The force can be your own body weight, like a push up or a squat, or a resistance band or a light weight. Bodyweight exercises are a perfect start because they need no equipment and are easy to control.\n\nNow watch this. The squat works the thighs and hips. Keep your chest up, push your hips back and keep your knees in line with your toes. The push up works chest, shoulders and arms. Start on your knees if you need to. The plank holds your body straight from head to heels to build the core. The lunge works the legs and balance.\n\nLook at the plan. A set is a group of reps. A beginner might do one or two sets of 8 to 12 reps, with a rest of 30 to 60 seconds, working each major muscle group two or three days a week with a rest day between. Breathe out on the effort and never hold your breath.\n\nHere are the safety rules. Never try to lift the heaviest weight you can. Never use heavy free weights without a trained adult and a spotter. Stop at sharp pain. And stay away from steroids and any powder or pill promising fast muscle.\n\nYour task is to name five bodyweight exercises, design a beginner routine and list four safety rules. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Bodyweight and Resistance Training$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Flexibility and Mobility$j$, $j${"readings": [{"title": "Matthew 11 (King James Version)", "url": "/portal/bible/Matthew/11"}], "body": "Flexibility is the range of motion at a joint. Good flexibility helps you move well, protects against some injuries, relieves muscle tightness and improves posture. Mobility means moving a joint smoothly through its full range with control.\n\nThere are two main kinds of stretching. Dynamic stretching uses controlled movement, such as arm circles, leg swings, walking lunges and high knees, and fits the warm up before activity. Static stretching holds a position without bouncing. Hold each stretch for about 15 to 30 seconds, until you feel a gentle pull, never pain. Static stretching is best after exercise or at another time when muscles are warm. Stretching cold muscles hard, or bouncing, can cause injury.\n\nBasic static stretches include the calf stretch, the standing quadriceps stretch, the seated hamstring stretch, the shoulder stretch across the chest, the triceps stretch and the butterfly stretch for the inner thigh. Stretch the major muscle groups, breathe slowly and relax. Practice flexibility at least 2 or 3 days a week, and daily is better.\n\nActivities such as yoga, dance and swimming also improve flexibility. If an activity includes practices that conflict with your faith, such as chanting or spiritual meditation to other gods, a student may choose the physical stretches only, or select another activity. Rest is also part of wellness. Matthew 11:28 says, Come unto me, all ye that labour and are heavy laden, and I will give you rest.\n\nYour task: (1) Define flexibility and explain two benefits. (2) Compare dynamic and static stretching and tell when to use each. (3) Make a five minute stretching routine for the major muscle groups.\n\nFlorida standards: PE.912.M.1, PE.912.L.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.M.1, PE.912.L.3", "script": "Welcome back. Listen, a strong body that cannot bend breaks easily. Flexibility matters.\n\nFlexibility is the range of motion at a joint. Good flexibility helps you move well, relieves tight muscles, improves posture and protects you from some injuries. Mobility is moving a joint smoothly through its full range with control.\n\nNow watch this. There are two main kinds of stretching. Dynamic stretching uses controlled movement, like arm circles, leg swings and walking lunges, and fits the warm up. Static stretching holds a position without bouncing. Hold each stretch for 15 to 30 seconds, until you feel a gentle pull, never pain. Static stretching is best after exercise when the muscles are warm. Never bounce, and never stretch cold muscles hard.\n\nLook at the basic stretches. The calf stretch. The standing quadriceps stretch. The seated hamstring stretch. The shoulder stretch across the chest. The triceps stretch. The butterfly stretch. Breathe slowly and relax. Stretch at least two or three days a week.\n\nRest matters too. Matthew 11:28 says, Come unto me, all ye that labour and are heavy laden, and I will give you rest.\n\nYour task is to define flexibility, compare dynamic and static stretching, and make a five minute routine. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Flexibility and Mobility$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Preventing and Treating Injuries$j$, $j${"readings": [{"title": "Luke 10 (King James Version)", "url": "/portal/bible/Luke/10"}], "body": "Most injuries can be prevented. Warm up and cool down, use proper shoes and safety gear such as helmets and mouth guards, learn correct form, increase activity gradually, rest when tired and follow the rules of the game. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself.\n\nKnow the common injuries. A sprain is a stretched or torn ligament. A strain is a stretched or torn muscle or tendon. A fracture is a broken bone. A bruise is bleeding under the skin. Muscle soreness a day or two after hard exercise is normal, but sharp pain, swelling, a joint that gives way, numbness or a deformity is not.\n\nFor minor sprains, strains and bruises, many people use the RICE method: Rest the injured part, apply Ice wrapped in a cloth for about 15 to 20 minutes at a time, use gentle Compression with a wrap, and Elevate the injured part above the heart. See a doctor if there is severe pain, a bone looks bent, the person cannot move or put weight on it, or swelling does not improve.\n\nA concussion is a brain injury from a blow to the head or body. Signs include headache, confusion, dizziness, nausea, blurred vision, memory trouble or loss of consciousness. A player with a suspected concussion must stop at once, tell an adult, see a health professional and not return to play until cleared by one.\n\nLearn first aid and CPR through the American Red Cross or the American Heart Association. If a person suddenly collapses and is not breathing normally, call 911, then push hard and fast in the center of the chest at about 100 to 120 compressions a minute, and use an automated external defibrillator, called an AED, if one is near. Jesus told of the Samaritan who bound up a stranger's wounds in Luke 10:34, a model of caring for others.\n\nYour task: (1) Name four injury prevention steps. (2) Explain the RICE method and when to seek a doctor. (3) List the signs of a concussion and what to do.\n\nFlorida standards: PE.912.R.5, PE.912.C.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.R.5, PE.912.C.2", "script": "Welcome back. Listen, the best treatment for an injury is to prevent it. Proverbs 22:3 says, A prudent man foreseeth the evil.\n\nTo prevent injury, warm up and cool down, wear proper shoes and safety gear like helmets and mouth guards, learn correct form, increase activity gradually, rest when tired and follow the rules of the game.\n\nNow watch this. A sprain is a stretched or torn ligament. A strain is a stretched or torn muscle or tendon. A fracture is a broken bone. Soreness a day or two after a hard workout is normal. Sharp pain, swelling, a joint that gives way, numbness or a bent bone is not.\n\nFor minor injuries, use RICE. Rest. Ice, wrapped in a cloth, for 15 to 20 minutes at a time. Compression with a wrap. Elevation above the heart. See a doctor for severe pain, a bent bone, or if the person cannot move or put weight on it.\n\nLook at concussions. Signs include headache, confusion, dizziness, nausea, blurred vision and memory trouble. Stop at once, tell an adult, see a health professional, and do not return until cleared.\n\nLearn CPR through the Red Cross or the American Heart Association. If someone collapses and is not breathing normally, call 911, push hard and fast in the center of the chest, about 100 to 120 times a minute, and use an AED if one is near. In Luke 10 the Samaritan bound up a stranger's wounds. Be ready to help.\n\nYour task is to name four prevention steps, explain RICE, and list concussion signs. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Preventing and Treating Injuries$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Strength, Endurance and Flexibility$j$, $j${"prompt": "Write a report of at least 250 words on strength, endurance and flexibility. Use complete sentences and label each part. Psalm 18:32 says, It is God that girdeth me with strength, and maketh my way perfect.\n\nPart 1: Describe the three kinds of muscle and explain how skeletal muscles work in pairs.\nPart 2: Explain how a muscle becomes stronger and why rest matters.\nPart 3: Design a beginner bodyweight routine with at least five exercises, naming sets, reps and rest, and give four safety rules.\nPart 4: Explain the difference between dynamic and static stretching and write a five minute stretching routine.\nPart 5: Explain how to prevent injuries, how to use the RICE method and the signs of a concussion. Attach or describe your activity log for two weeks, including at least four strength sessions.", "rubric": "100 points. Part 1: 15 points. Part 2: 15 points. Part 3: 25 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Strength, Endurance and Flexibility$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Strength, Safety and Care for Others$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells which strength or flexibility exercise you find hardest and how you will improve safely, (2) explains why a teen should avoid steroids and unproven supplements, (3) describes one way you can help an injured teammate, and (4) connects your answer to Luke 10:34, where the Samaritan bound up the wounds of a stranger. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why should an athlete with a suspected concussion never return to play the same day? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Strength, Safety and Care for Others$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Muscles and How They Work$j$, $j${"questions": [{"q": "The muscle that forms the heart is:", "options": ["A tendon", "Smooth muscle", "Cardiac muscle", "Skeletal muscle"]}, {"q": "Tendons connect:", "options": ["Muscle to bone", "Lung to heart", "Skin to muscle", "Bone to bone"]}, {"q": "When the biceps contracts, the triceps:", "options": ["Disappears", "Also contracts fully", "Turns into bone", "Relaxes"]}, {"q": "Muscles become stronger when they are:", "options": ["Worked a bit harder and then allowed to recover", "Never used", "Worked every hour without rest", "Kept in a cast"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Muscles and How They Work$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,0}'::int[], array[$j$Cardiac muscle beats without rest.$j$,$j$Ligaments connect bone to bone.$j$,$j$Muscles work in opposing pairs.$j$,$j$Overload and recovery build strength.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Muscles and How They Work$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Bodyweight and Resistance Training$j$, $j${"questions": [{"q": "A group of repetitions is called a:", "options": ["Circuit break", "Set", "Pace", "Rest"]}, {"q": "Which exercise is a bodyweight exercise?", "options": ["Resting", "Heavy lift without a spotter", "Push up", "Anabolic steroid use"]}, {"q": "During a hard lift or push, you should:", "options": ["Breathe out and never hold your breath", "Hold your breath", "Stop breathing", "Breathe only in"]}, {"q": "A beginner should avoid:", "options": ["Resting between sets", "Warming up", "Using good form", "Trying to lift the heaviest weight possible"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Bodyweight and Resistance Training$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,3}'::int[], array[$j$A set is a group of reps.$j$,$j$Bodyweight exercises use your own weight as resistance.$j$,$j$Holding the breath can raise blood pressure dangerously.$j$,$j$Maximum lifts are risky without training and a spotter.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Bodyweight and Resistance Training$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Flexibility and Mobility$j$, $j${"questions": [{"q": "Flexibility is:", "options": ["The range of motion at a joint", "Muscle size", "Running speed", "Body fat"]}, {"q": "Dynamic stretching:", "options": ["Is never safe", "Uses controlled movement and fits a warm up", "Is done only when injured", "Holds a bouncing stretch"]}, {"q": "A static stretch should be held about:", "options": ["1 second", "5 seconds with bouncing", "15 to 30 seconds", "10 minutes"]}, {"q": "Static stretching is best done:", "options": ["After exercise when muscles are warm", "Never", "Only before sleep", "On cold muscles with bouncing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Flexibility and Mobility$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,0}'::int[], array[$j$Flexibility describes how far a joint can move.$j$,$j$Arm circles and leg swings are dynamic stretches.$j$,$j$Hold gently without bouncing or pain.$j$,$j$Warm muscles stretch more safely.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Flexibility and Mobility$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Preventing and Treating Injuries$j$, $j${"questions": [{"q": "A sprain is an injury to a:", "options": ["Lung", "Nerve only", "Ligament", "Fingernail"]}, {"q": "In RICE, the letter C stands for:", "options": ["Cooling", "Compression", "Catching", "Cardio"]}, {"q": "A student with a suspected concussion should:", "options": ["Hide symptoms", "Drink energy drinks", "Keep playing", "Stop and see a health professional before returning"]}, {"q": "If a person collapses and is not breathing normally, you should first:", "options": ["Wait to see what happens", "Call 911 and begin chest compressions", "Shake them hard", "Give water"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Preventing and Treating Injuries$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,1}'::int[], array[$j$A sprain stretches or tears a ligament.$j$,$j$RICE means rest, ice, compression and elevation.$j$,$j$Return to play only when cleared by a professional.$j$,$j$Fast help and compressions save lives.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Preventing and Treating Injuries$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Strength, Endurance and Flexibility$j$, $j${"questions": [{"q": "Muscles work in pairs because they can only:", "options": ["Push", "Grow", "Rest", "Pull"]}, {"q": "Ligaments connect:", "options": ["Lung to heart", "Bone to bone", "Muscle to bone", "Skin to fat"]}, {"q": "Which exercise builds core strength?", "options": ["Napping", "Deep sea diving", "Plank", "Sitting still"]}, {"q": "A beginner routine might include:", "options": ["Maximum lifts", "1 or 2 sets of 8 to 12 reps", "100 sets of one rep", "No rest at all"]}, {"q": "Anabolic steroids are:", "options": ["Dangerous and illegal without a prescription", "Healthy foods", "Safe for teens", "Required for sports"]}, {"q": "Bouncing during a static stretch can:", "options": ["Warm the body", "Improve safety", "Heal a sprain", "Cause injury"]}, {"q": "RICE stands for rest, ice, compression and:", "options": ["Elevation", "Endurance", "Exercise", "Energy"]}, {"q": "CPR compressions are given at about:", "options": ["1 per minute", "100 to 120 per minute", "300 per minute", "10 per minute"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Strength, Endurance and Flexibility$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,2,1,0,3,0,1}'::int[], array[$j$Muscles pull, so opposing muscles are needed to reverse the motion.$j$,$j$Ligaments stabilize joints.$j$,$j$A plank holds the body straight and works the core.$j$,$j$Moderate sets and reps with good form suit beginners.$j$,$j$They carry serious health risks.$j$,$j$Hold stretches gently and steadily.$j$,$j$Elevate the injured part above the heart.$j$,$j$A fast steady rhythm keeps blood moving.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Strength, Endurance and Flexibility$j$ on conflict (item_id) do nothing;
